const item = $input.item.json;

// Calcula dia da semana em São Paulo (UTC-3)
const now = new Date();
const spTime = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dow = spTime.getDay(); // 0=Dom, 1=Seg ... 6=Sab

const dias = ['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
const isWeekend = dow === 0 || dow === 6;

return [{
  json: {
    ...item,
    dow,
    dia_semana: dias[dow],
    is_weekend: isWeekend
  }
}];

// Dados das tarefas (nó atual)
const taskData = $input.item.json;
// Contexto do usuário
const userData = $('📅 Dia da Semana1').item.json;

// Parse seguro de arrays JSON
const parseArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  try { return JSON.parse(v); } catch { return []; }
};

const nome      = userData.frist_name || 'você';
const gender    = (userData.gender || 'masculino').toLowerCase();
const dia       = userData.dia_semana;
const feitas    = parseArr(taskData.feitas_hoje);
const pendentes = parseArr(taskData.pendentes_hoje);
const atrasadas = parseArr(taskData.atrasadas);

// Formata listas
const fmtFeita = (t, i) => {
  const h = t.horario && t.horario !== 'null' ? ` às ${t.horario.substring(0,5)}` : '';
  return `${i+1}. ✅ ${t.titulo}${h} — ${t.categoria}`;
};
const fmtPendente = (t, i) => {
  const h = t.horario && t.horario !== 'null' ? ` às ${t.horario.substring(0,5)}` : '';
  return `${i+1}. ⏳ ${t.titulo}${h} — ${t.categoria}`;
};
const fmtAtrasada = (t, i) =>
  `${i+1}. ⚠️ ${t.titulo} (desde ${t.data}) — ${t.categoria}`;

const blocoFeitas = feitas.length > 0
  ? `✅ *${feitas.length} tarefa(s) concluída(s) hoje:*\n${feitas.map(fmtFeita).join('\n')}`
  : '📭 Nenhuma tarefa marcada como concluída hoje.';

const blocoPendentes = pendentes.length > 0
  ? `⏳ *${pendentes.length} tarefa(s) pendente(s) de hoje:*\n${pendentes.map(fmtPendente).join('\n')}`
  : '✅ Todas as tarefas de hoje foram resolvidas!';

const blocoAtrasadas = atrasadas.length > 0
  ? `⚠️ *${atrasadas.length} tarefa(s) em atraso:*\n${atrasadas.map(fmtAtrasada).join('\n')}`
  : '🎉 Nenhuma tarefa em atraso!';

const suf = gender === 'feminino' ? 'a' : 'o';

const userPrompt =
  `Gere a mensagem de fechamento de ${dia} para ${nome}.\n\n` +
  `BALANÇO DO DIA:\n` +
  `${blocoFeitas}\n\n` +
  `${blocoPendentes}\n\n` +
  `${blocoAtrasadas}\n\n` +
  `Lembre: tom acolhed${suf}, sem culpa, celebre o que foi feit${suf} e ajude a planejar o que fica para amanhã.`;

return [{
  json: {
    user_phone: userData.user_phone,
    frist_name: nome,
    user_prompt: userPrompt
  }
}];

